using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;
using System;

[MemoryDiagnoser]
[Orderer(BenchmarkDotNet.Order.SummaryOrderPolicy.FastestToSlowest)]
[RankColumn]
public class TextParsingBenchmark
{
    private const string Payload = "ORDER_ID=98234;CUSTOMER=CORP_CORP;AMOUNT=4523.50;CURRENCY=USD;STATUS=SETTLED";

    [Benchmark(Baseline = true)]
    public decimal ParseAmountLegacy()
    {
        // Legacy: Multiple string allocations, array allocation, and GC churn
        string[] parts = Payload.Split(';');
        foreach (string part in parts)
        {
            if (part.StartsWith("AMOUNT="))
            {
                string value = part.Substring(7);
                return decimal.Parse(value);
            }
        }
        return 0m;
    }

    [Benchmark]
    public decimal ParseAmountZeroAlloc()
    {
        // Modern C# 13: Zero heap allocations, pure stack ReadOnlySpan
        ReadOnlySpan<char> span = Payload.AsSpan();
        Span<Range> ranges = stackalloc Range[8];
        int count = span.Split(ranges, ';');

        for (int i = 0; i < count; i++)
        {
            ReadOnlySpan<char> segment = span[ranges[i]];
            if (segment.StartsWith("AMOUNT=".AsSpan()))
            {
                ReadOnlySpan<char> value = segment.Slice(7);
                return decimal.Parse(value);
            }
        }
        return 0m;
    }
}
